Method.Source:
[
    DataMemberAttribute,
    AifQueryTypeAttribute(identifierStr(_packedQuery), queryStr(WHSCycleCountCreateItem))
]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

public void initFromRecord(Common _record)
{
    Query           query;
    QueryBuildRange queryBuildRange;
    WMSLocationId   wmsLocationId;
    ItemId          itemId;

    InventSum       inventSum;
    InventDim       inventDim;

    if (_record)
    {
        switch (_record.TableId)
        {
            case tableNum(InventSum):
                inventSum   = _record;
                inventDim   = InventDim::find(inventSum.inventDimId);

                itemId          = inventSum.ItemId;
                wmsLocationId   = inventDim.wmsLocationId;
                break;

            //Todo develop other call points

        }

        query = this.getQuery();

        if (itemId)
        {
            queryBuildRange = SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(InventSum)), fieldNum(InventSum, ItemId));
            queryBuildRange.value(queryValue(itemId));
            queryBuildRange.status(RangeStatus::Locked);
        }

        if (wmsLocationId)
        {
            queryBuildRange = SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(InventDim)), fieldNum(InventDim, wmsLocationId));
            queryBuildRange.value(queryValue(wmsLocationId));
            queryBuildRange.status(RangeStatus::Locked);
        }


        this.setQuery(query);
    }
}

